CREATE DATABASE IF NOT EXISTS mk3_multimarcas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mk3_multimarcas;
CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,session_version INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,brand VARCHAR(100) NOT NULL DEFAULT '',model VARCHAR(120) NOT NULL DEFAULT '',year_model VARCHAR(20) DEFAULT NULL,mileage INT UNSIGNED DEFAULT NULL,transmission VARCHAR(60) DEFAULT NULL,fuel VARCHAR(60) DEFAULT NULL,color VARCHAR(60) DEFAULT NULL,price DECIMAL(12,2) DEFAULT NULL,description TEXT,version VARCHAR(120) NOT NULL DEFAULT '',manufacture_year SMALLINT UNSIGNED NULL,model_year SMALLINT UNSIGNED NULL,features TEXT NULL,featured_order INT UNSIGNED NOT NULL DEFAULT 0,status ENUM('available','reserved','sold','hidden') NOT NULL DEFAULT 'available',featured TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status,featured)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS photos(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vehicle_id INT UNSIGNED NOT NULL,path VARCHAR(255) NOT NULL,position INT NOT NULL DEFAULT 0,CONSTRAINT fk_vehicle_photo FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip VARCHAR(45) NOT NULL,subject_hash CHAR(64) NULL,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip,attempted_at),INDEX(subject_hash,attempted_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,action VARCHAR(80) NOT NULL,target VARCHAR(255),ip VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS store_settings(setting_key VARCHAR(60) PRIMARY KEY,setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
